// handoff: ADM-W1-7NOIVE

export interface RateLimiterOptions {
  /** Maximum tokens per key. A new key starts full. */
  capacity: number;
  /** Tokens added per second, continuously. */
  refillPerSecond: number;
  /** Clock in milliseconds. Defaults to Date.now. */
  now?: () => number;
}

export interface TakeResult {
  allowed: boolean;
  /** Whole tokens left after the call. */
  remaining: number;
  /** 0 when allowed, otherwise milliseconds until `cost` tokens are available. */
  retryAfterMs: number;
}

export interface RateLimiter {
  take(key: string, cost?: number): TakeResult;
}

interface Bucket {
  tokens: number;
  updatedAt: number;
}

/** Absorbs floating point error from continuous refill, e.g. 0.1 * 10 !== 1. */
const EPSILON = 1e-9;

/** A token bucket per key. */
export function createRateLimiter(options: RateLimiterOptions): RateLimiter {
  const { capacity, refillPerSecond } = options;
  const now = options.now ?? Date.now;
  if (!Number.isInteger(capacity) || capacity < 1) {
    throw new RangeError(`capacity must be an integer >= 1, got ${capacity}`);
  }
  if (!Number.isFinite(refillPerSecond) || refillPerSecond <= 0) {
    throw new RangeError(`refillPerSecond must be a finite number > 0, got ${refillPerSecond}`);
  }

  const buckets = new Map<string, Bucket>();

  function take(key: string, cost = 1): TakeResult {
    if (!Number.isInteger(cost) || cost < 1 || cost > capacity) {
      throw new RangeError(`cost must be an integer from 1 to ${capacity}, got ${cost}`);
    }

    const time = now();
    let bucket = buckets.get(key);
    if (bucket === undefined) {
      bucket = { tokens: capacity, updatedAt: time };
      buckets.set(key, bucket);
    } else {
      // A clock that moves backwards adds nothing instead of removing tokens.
      const elapsedMs = Math.max(0, time - bucket.updatedAt);
      bucket.tokens = Math.min(capacity, bucket.tokens + (elapsedMs / 1000) * refillPerSecond);
      bucket.updatedAt = Math.max(bucket.updatedAt, time);
    }

    if (bucket.tokens + EPSILON >= cost) {
      bucket.tokens = Math.max(0, bucket.tokens - cost);
      return { allowed: true, remaining: wholeTokens(bucket.tokens), retryAfterMs: 0 };
    }

    const missing = cost - bucket.tokens;
    return {
      allowed: false,
      remaining: wholeTokens(bucket.tokens),
      retryAfterMs: Math.ceil((missing / refillPerSecond) * 1000),
    };
  }

  return { take };
}

function wholeTokens(tokens: number): number {
  return Math.floor(tokens + EPSILON);
}

