import test from "node:test";
import assert from "node:assert/strict";
import { createRateLimiter } from "../src/rate-limiter.ts";
import { createApp } from "../src/api.ts";
import { sampleInvoices } from "../src/invoices.ts";

function clock(start = 1_000_000) {
  let time = start;
  return {
    now: () => time,
    advance(ms: number) {
      time += ms;
    },
  };
}

test("a new key starts with capacity tokens", () => {
  const limiter = createRateLimiter({ capacity: 3, refillPerSecond: 1, now: clock().now });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 2, retryAfterMs: 0 });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 1, retryAfterMs: 0 });
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 0, retryAfterMs: 0 });
  assert.deepEqual(limiter.take("a"), { allowed: false, remaining: 0, retryAfterMs: 1000 });
});

test("keys have separate buckets", () => {
  const limiter = createRateLimiter({ capacity: 1, refillPerSecond: 1, now: clock().now });
  assert.equal(limiter.take("a").allowed, true);
  assert.equal(limiter.take("a").allowed, false);
  assert.equal(limiter.take("b").allowed, true);
});

test("tokens refill continuously and never exceed capacity", () => {
  const time = clock();
  const limiter = createRateLimiter({ capacity: 5, refillPerSecond: 2, now: time.now });
  limiter.take("a", 5);
  time.advance(250);
  // 0.5 tokens: not enough for one.
  assert.deepEqual(limiter.take("a"), { allowed: false, remaining: 0, retryAfterMs: 250 });
  time.advance(250);
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 0, retryAfterMs: 0 });
  time.advance(60_000);
  assert.deepEqual(limiter.take("a"), { allowed: true, remaining: 4, retryAfterMs: 0 });
});

test("a denied take removes nothing", () => {
  const time = clock();
  const limiter = createRateLimiter({ capacity: 4, refillPerSecond: 1, now: time.now });
  limiter.take("a", 2);
  assert.deepEqual(limiter.take("a", 3), { allowed: false, remaining: 2, retryAfterMs: 1000 });
