// Date tests that must pass in every time zone. test/dates.test.ts runs this
// file in-process and again in child processes under several TZ values.
import test from "node:test";
import assert from "node:assert/strict";
import { addDays, daysOverdue, dueDate, formatDay, isOverdue, parseDay } from "../../src/dates.ts";

const zone = process.env.TZ ?? "(default)";

test(`[${zone}] parseDay returns UTC midnight of the day`, () => {
  assert.equal(parseDay("2026-03-01").toISOString(), "2026-03-01T00:00:00.000Z");
  assert.equal(parseDay("2024-02-29").toISOString(), "2024-02-29T00:00:00.000Z");
  assert.equal(parseDay("0050-06-15").toISOString(), "0050-06-15T00:00:00.000Z");
});

test(`[${zone}] parseDay rejects malformed and impossible days`, () => {
  for (const day of ["2026-3-01", "2026-03-01T00:00", "", "2026-02-30", "2025-02-29", "2026-13-01", "2026-00-10", "2026-04-31"]) {
    assert.throws(() => parseDay(day), RangeError, day);
  }
});

test(`[${zone}] formatDay is the inverse of parseDay`, () => {
  for (const day of ["2026-01-01", "2026-03-08", "2026-03-31", "2026-11-01", "2026-12-31", "2024-02-29", "0050-06-15"]) {
    assert.equal(formatDay(parseDay(day)), day);
  }
  assert.equal(formatDay(new Date("2026-03-31T23:59:59.999Z")), "2026-03-31");
  assert.throws(() => formatDay(new Date(Number.NaN)), RangeError);
});

test(`[${zone}] addDays crosses months, years and DST changes`, () => {
  assert.equal(addDays("2026-03-01", 30), "2026-03-31");
  assert.equal(addDays("2026-03-07", 1), "2026-03-08");
  assert.equal(addDays("2026-03-08", 1), "2026-03-09");
  assert.equal(addDays("2026-10-31", 1), "2026-11-01");
  assert.equal(addDays("2026-11-01", 1), "2026-11-02");
  assert.equal(addDays("2026-12-31", 1), "2027-01-01");
  assert.equal(addDays("2024-02-28", 1), "2024-02-29");
  assert.equal(addDays("2026-03-31", -31), "2026-02-28");
  assert.equal(addDays("2026-05-05", 0), "2026-05-05");
});

test(`[${zone}] dueDate adds netDays to the issue date`, () => {
  assert.equal(dueDate({ issued: "2026-03-01", netDays: 30 }), "2026-03-31");
  assert.equal(dueDate({ issued: "2026-01-15", netDays: 0 }), "2026-01-15");
  assert.equal(dueDate({ issued: "2025-12-20", netDays: 45 }), "2026-02-03");
});

test(`[${zone}] daysOverdue and isOverdue count whole calendar days`, () => {
