export interface Page<T> {
  items: T[];
  /** 1-based page number. */
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  hasPrevious: boolean;
  hasNext: boolean;
}

/** Offset pagination over a fixed list. The API uses cursorPage() instead. */
export function paginate<T>(all: readonly T[], page: number, pageSize: number): Page<T> {
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError(`page must be an integer >= 1, got ${page}`);
  }
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new RangeError(`pageSize must be an integer >= 1, got ${pageSize}`);
  }

  const totalItems = all.length;
  const totalPages = Math.ceil(totalItems / pageSize);
  const start = (page - 1) * pageSize;

  return {
    items: all.slice(start, start + pageSize),
    page,
    pageSize,
    totalItems,
    totalPages,
    hasPrevious: page > 1,
    hasNext: page < totalPages,
  };
}

/** Thrown by cursorPage() when the cursor was not produced by cursorPage(). */
export class BadCursorError extends Error {
  constructor() {
    super("malformed cursor");
    this.name = "BadCursorError";
  }
}

export interface CursorPage<T> {
  items: T[];
  /** null on the last page. */
  nextCursor: string | null;
}

/**
 * What a cursor encodes: the last key returned, and the highest key that existed
 * when the first page was requested. Pages never go past `until`, so following
 * the cursors walks a snapshot of the keys from the first request, each exactly
 * once, even when items with higher keys are added in between.
 */
interface CursorState {
  after: string;
  until: string;
}

const CURSOR_VERSION = 1;
const BASE64URL = /^[A-Za-z0-9_-]+$/;

function encodeCursor(state: CursorState): string {
  return Buffer.from(JSON.stringify([CURSOR_VERSION, state.after, state.until])).toString("base64url");
}

function decodeCursor(cursor: string): CursorState {
  if (!BASE64URL.test(cursor)) throw new BadCursorError();
  let value: unknown;
  try {
    value = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
  } catch {
    throw new BadCursorError();
  }
  if (
    !Array.isArray(value) ||
    value.length !== 3 ||
    value[0] !== CURSOR_VERSION ||
    typeof value[1] !== "string" ||
    typeof value[2] !== "string" ||
    value[1] > value[2]
  ) {
    throw new BadCursorError();
  }
  return { after: value[1], until: value[2] };
}

function compareKeys(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Keyset pagination ordered by key, ascending (plain string order). Pass the
 * cursor from the previous page's nextCursor, or undefined for the first page.
 * Throws BadCursorError for a malformed cursor and RangeError for a bad limit.
 */
export function cursorPage<T>(
  all: readonly T[],
  keyOf: (item: T) => string,
  limit: number,
  cursor?: string,
): CursorPage<T> {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new RangeError(`limit must be an integer >= 1, got ${limit}`);
  }
  const sorted = [...all].sort((a, b) => compareKeys(keyOf(a), keyOf(b)));
  if (sorted.length === 0 && cursor === undefined) {
    return { items: [], nextCursor: null };
  }

  const state = cursor === undefined ? undefined : decodeCursor(cursor);
  const until = state?.until ?? keyOf(sorted[sorted.length - 1]!);
  const window = sorted.filter((item) => {
    const key = keyOf(item);
    return (state === undefined || key > state.after) && key <= until;
  });

  const items = window.slice(0, limit);
  const hasMore = window.length > limit;
  return {
    items,
    nextCursor: hasMore ? encodeCursor({ after: keyOf(items[items.length - 1]!), until }) : null,
  };
}

