import { dueDate } from "./dates.ts";
import { sampleInvoices, totalCents } from "./invoices.ts";
import type { Invoice } from "./invoices.ts";
import { BadCursorError, cursorPage } from "./paginate.ts";
import { createRateLimiter } from "./rate-limiter.ts";

export interface Request {
  method: string;
  /** Path with an optional query string, for example `/invoices?limit=50`. */
  path: string;
  /** Header names are lowercase. */
  headers?: Record<string, string>;
}

export interface Response {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface AppOptions {
  invoices?: Invoice[];
  /** Token bucket per x-api-key. Off when omitted. */
  rateLimit?: { capacity: number; refillPerSecond: number; now?: () => number };
}

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function json(status: number, body: unknown, headers: Record<string, string> = {}): Response {
  return { status, headers: { "content-type": "application/json", ...headers }, body };
}

function toSummary(invoice: Invoice) {
  return {
    id: invoice.id,
    client: invoice.client,
    status: invoice.status,
    currency: invoice.currency,
    totalCents: totalCents(invoice),
    due: dueDate(invoice),
  };
}

export function createApp(options: AppOptions = {}) {
  const invoices = options.invoices ?? sampleInvoices(57);
  const byId = new Map(invoices.map((invoice) => [invoice.id, invoice]));

  const limiter = options.rateLimit ? createRateLimiter(options.rateLimit) : undefined;

  function handle(request: Request): Response {
    const url = new URL(request.path, "http://ledger.local");
    if (!limiter || (request.method === "GET" && url.pathname === "/health")) {
      return route(request, url);
    }

    const key = request.headers?.["x-api-key"] ?? "anonymous";
    const result = limiter.take(key);
    const response = result.allowed
      ? route(request, url)
      : json(429, { error: "rate_limited" }, {
          "retry-after": String(Math.max(1, Math.ceil(result.retryAfterMs / 1000))),
        });
    return {
      ...response,
      headers: { ...response.headers, "x-ratelimit-remaining": String(result.remaining) },
    };
  }

  function route(request: Request, url: URL): Response {
    if (request.method !== "GET") {
      return json(405, { error: "method_not_allowed" });
    }
    if (url.pathname === "/health") {
      return json(200, { ok: true });
    }
    if (url.pathname === "/invoices") {
      return listInvoices(url.searchParams);
    }

    const match = /^\/invoices\/([\w-]+)$/.exec(url.pathname);
    if (match) {
      const invoice = byId.get(match[1]!);
      return invoice ? json(200, invoice) : json(404, { error: "not_found" });
    }
    return json(404, { error: "not_found" });
  }

  /** GET /invoices?limit=<1-100>&cursor=<nextCursor> */
  function listInvoices(params: URLSearchParams): Response {
    if (params.has("page") || params.has("pageSize")) {
      return json(400, { error: "use_cursor" });
    }
    const limitParam = params.get("limit");
    const limit = limitParam === null ? DEFAULT_LIMIT : /^\d{1,3}$/.test(limitParam) ? Number(limitParam) : NaN;
    if (!(limit >= 1 && limit <= MAX_LIMIT)) {
      return json(400, { error: "bad_request", message: `limit must be an integer from 1 to ${MAX_LIMIT}` });
    }
    try {
      const page = cursorPage(invoices, (invoice) => invoice.id, limit, params.get("cursor") ?? undefined);
      return json(200, { items: page.items.map(toSummary), nextCursor: page.nextCursor, limit });
    } catch (error) {
      if (error instanceof BadCursorError) {
        return json(400, { error: "bad_cursor" });
      }
      throw error;
    }
  }

  return { handle };
}

