import test from "node:test";
import assert from "node:assert/strict";
import { BadCursorError, cursorPage, paginate } from "../src/paginate.ts";

const letters = ["a", "b", "c", "d", "e", "f", "g"];

test("paginate returns at most pageSize items", () => {
  assert.deepEqual(paginate(letters, 1, 3).items, ["a", "b", "c"]);
  assert.deepEqual(paginate(letters, 2, 3).items, ["d", "e", "f"]);
  assert.deepEqual(paginate(letters, 3, 3).items, ["g"]);
  assert.deepEqual(paginate(letters, 4, 3).items, []);
});

test("paginate pages do not overlap and cover every item", () => {
  const seen = [1, 2, 3].flatMap((page) => paginate(letters, page, 3).items);
  assert.deepEqual(seen, letters);
});

test("paginate hasNext is false on the last page", () => {
  assert.equal(paginate(letters, 1, 3).hasNext, true);
  assert.equal(paginate(letters, 2, 3).hasNext, true);
  assert.equal(paginate(letters, 3, 3).hasNext, false);
  assert.equal(paginate(letters, 1, 7).hasNext, false);
  assert.equal(paginate([], 1, 3).hasNext, false);
  assert.deepEqual(
    { ...paginate(letters, 3, 3), items: undefined },
    { items: undefined, page: 3, pageSize: 3, totalItems: 7, totalPages: 3, hasPrevious: true, hasNext: false },
  );
});

test("paginate rejects bad page and pageSize", () => {
  assert.throws(() => paginate(letters, 0, 3), RangeError);
  assert.throws(() => paginate(letters, 1, 0), RangeError);
  assert.throws(() => paginate(letters, 1.5, 3), RangeError);
});

test("cursorPage walks items in key order", () => {
  const all = ["d", "a", "g", "c", "b", "f", "e"];
  const pages: string[][] = [];
  let cursor: string | undefined;
  do {
    const page = cursorPage(all, (x) => x, 3, cursor);
    pages.push(page.items);
    cursor = page.nextCursor ?? undefined;
  } while (cursor);
  assert.deepEqual(pages, [["a", "b", "c"], ["d", "e", "f"], ["g"]]);
});

test("cursorPage returns a null cursor when the last page is exactly full", () => {
  const first = cursorPage(["a", "b", "c", "d"], (x) => x, 2);
  assert.ok(first.nextCursor);
  const second = cursorPage(["a", "b", "c", "d"], (x) => x, 2, first.nextCursor);
  assert.deepEqual(second, { items: ["c", "d"], nextCursor: null });
  assert.deepEqual(cursorPage([], (x: string) => x, 2), { items: [], nextCursor: null });
});

test("cursorPage rejects malformed cursors", () => {
  const valid = cursorPage(letters, (x) => x, 2).nextCursor!;
  const json = (value: unknown) => Buffer.from(JSON.stringify(value)).toString("base64url");
  for (const cursor of ["", "!!", "abc", valid + "*", json({ after: "a" }), json([2, "a", "z"]), json([1, "z", "a"]), json([1, 1, "z"])]) {
    assert.throws(() => cursorPage(letters, (x) => x, 2, cursor), BadCursorError, cursor);
  }
});
