import test from "node:test";
import assert from "node:assert/strict";
import { createApp } from "../src/api.ts";
import { sampleInvoices } from "../src/invoices.ts";
import type { Invoice } from "../src/invoices.ts";

interface ListBody {
  items: Array<{ id: string }>;
  nextCursor: string | null;
  limit: number;
}

function get(app: ReturnType<typeof createApp>, path: string) {
  return app.handle({ method: "GET", path });
}

function walk(app: ReturnType<typeof createApp>, limit: number, between?: () => void): string[] {
  const ids: string[] = [];
  let path = `/invoices?limit=${limit}`;
  for (;;) {
    const response = get(app, path);
    assert.equal(response.status, 200);
    const body = response.body as ListBody;
    assert.ok(body.items.length <= limit);
    ids.push(...body.items.map((item) => item.id));
    if (body.nextCursor === null) return ids;
    between?.();
    path = `/invoices?limit=${limit}&cursor=${encodeURIComponent(body.nextCursor)}`;
  }
}

test("GET /invoices returns the first 20 summaries ordered by id", () => {
  const invoices = sampleInvoices(57).reverse();
  const app = createApp({ invoices });
  const response = get(app, "/invoices");
  assert.equal(response.status, 200);
  const body = response.body as ListBody;
  assert.equal(body.limit, 20);
  assert.equal(body.items.length, 20);
  assert.equal(typeof body.nextCursor, "string");
  assert.deepEqual(
    body.items.map((item) => item.id),
    Array.from({ length: 20 }, (_, i) => `INV-${String(1001 + i).padStart(5, "0")}`),
  );
  assert.deepEqual(Object.keys(body.items[0]!).sort(), ["client", "currency", "due", "id", "status", "totalCents"]);
});

test("following nextCursor returns every invoice exactly once", () => {
  const app = createApp({ invoices: sampleInvoices(57) });
  const expected = sampleInvoices(57).map((invoice) => invoice.id);
  for (const limit of [1, 7, 19, 20, 57, 100]) {
    assert.deepEqual(walk(app, limit), expected, `limit ${limit}`);
  }
});

test("invoices added between requests do not cause repeats or gaps", () => {
  const invoices = sampleInvoices(57);
  const expected = invoices.map((invoice) => invoice.id);
  const app = createApp({ invoices });
  let next = 2000;
  const extra = sampleInvoices(30, 9);
  const ids = walk(app, 10, () => {
    invoices.push({ ...extra.pop()!, id: `INV-0${next++}` });
  });
  assert.deepEqual(ids, expected);
});

test("nextCursor is null on the last page", () => {
  const app = createApp({ invoices: sampleInvoices(40) });
  const first = get(app, "/invoices?limit=20").body as ListBody;
  const last = get(app, `/invoices?limit=20&cursor=${first.nextCursor}`).body as ListBody;
  assert.equal(last.items.length, 20);
  assert.equal(last.nextCursor, null);
  const empty = createApp({ invoices: [] });
  assert.deepEqual(get(empty, "/invoices").body, { items: [], nextCursor: null, limit: 20 });
});

test("limit must be an integer from 1 to 100", () => {
  const app = createApp({ invoices: sampleInvoices(5) });
  for (const limit of ["0", "101", "-1", "1.5", "abc", "", "1e2", " 5"]) {
    const response = get(app, `/invoices?limit=${encodeURIComponent(limit)}`);
    assert.equal(response.status, 400, `limit ${JSON.stringify(limit)}`);
    assert.deepEqual(response.body, { error: "bad_request" });
  }
  for (const limit of ["1", "100"]) {
    assert.equal(get(app, `/invoices?limit=${limit}`).status, 200);
  }
});

test("a malformed cursor returns bad_cursor", () => {
  const app = createApp({ invoices: sampleInvoices(5) });
  for (const cursor of ["", "nope!", "eyJ4IjoxfQ", "W10"]) {
    const response = get(app, `/invoices?cursor=${encodeURIComponent(cursor)}`);
    assert.equal(response.status, 400, `cursor ${JSON.stringify(cursor)}`);
    assert.deepEqual(response.body, { error: "bad_cursor" });
  }
});

test("page and pageSize are rejected with use_cursor", () => {
  const app = createApp({ invoices: sampleInvoices(5) });
  for (const query of ["page=1", "pageSize=10", "page=2&pageSize=5", "limit=5&page=1"]) {
    const response = get(app, `/invoices?${query}`);
    assert.equal(response.status, 400, query);
    assert.deepEqual(response.body, { error: "use_cursor" });
  }
});

test("ordering is by id even when the list is shuffled", () => {
  const invoices: Invoice[] = sampleInvoices(3).map((invoice, i) => ({ ...invoice, id: ["INV-00300", "INV-00100", "INV-00200"][i]! }));
  const app = createApp({ invoices });
  assert.deepEqual(walk(app, 2), ["INV-00100", "INV-00200", "INV-00300"]);
});
