import { addDays, parseDay } from "./dates.ts";
import type { Currency, Invoice, LineItem, Status } from "./invoices.ts";

export type NewInvoice = Omit<Invoice, "id">;

export type ParseResult = { ok: true; invoice: NewInvoice } | { ok: false; message: string };

const CURRENCIES: readonly Currency[] = ["USD", "EUR", "MXN"];
const STATUSES: readonly Status[] = ["draft", "sent", "paid", "void"];

class InvalidInvoice extends Error {}

function fail(message: string): never {
  throw new InvalidInvoice(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function integerAtLeast(value: unknown, min: number, field: string): number {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value < min) {
    fail(`${field} must be an integer >= ${min}`);
  }
  return value;
}

function parseItem(value: unknown, index: number): LineItem {
  const field = `items[${index}]`;
  if (!isRecord(value)) fail(`${field} must be an object`);
  const { description = "", quantity, unitPriceCents, taxRate } = value;
  if (typeof description !== "string") fail(`${field}.description must be a string`);
  if (typeof taxRate !== "number" || !(taxRate >= 0 && taxRate <= 1)) {
    fail(`${field}.taxRate must be a number from 0 to 1`);
  }
  return {
    description,
    quantity: integerAtLeast(quantity, 1, `${field}.quantity`),
    unitPriceCents: integerAtLeast(unitPriceCents, 0, `${field}.unitPriceCents`),
    taxRate,
  };
}

function parse(body: unknown): NewInvoice {
  if (!isRecord(body)) fail("body must be a JSON object");
  const { client, issued, netDays, currency, items, status = "draft" } = body;

  if (typeof client !== "string" || client.trim() === "") fail("client must be a non-empty string");

  if (typeof issued !== "string") fail("issued must be a date in YYYY-MM-DD form");
  try {
    parseDay(issued);
  } catch {
    fail("issued must be a date in YYYY-MM-DD form");
  }

  const days = integerAtLeast(netDays, 0, "netDays");
  try {
    addDays(issued, days);
  } catch {
    fail("netDays puts the due date after 9999-12-31");
  }

  if (!CURRENCIES.includes(currency as Currency)) fail(`currency must be one of ${CURRENCIES.join(", ")}`);
  if (!STATUSES.includes(status as Status)) fail(`status must be one of ${STATUSES.join(", ")}`);

  if (!Array.isArray(items) || items.length === 0) fail("items must be an array with at least one item");

  return {
    client,
    issued,
    netDays: days,
    status: status as Status,
    currency: currency as Currency,
    items: items.map(parseItem),
  };
}

/** Validates a POST /invoices body. Unknown fields are ignored. */
export function parseNewInvoice(body: unknown): ParseResult {
  try {
    return { ok: true, invoice: parse(body) };
  } catch (error) {
    if (error instanceof InvalidInvoice) return { ok: false, message: error.message };
    throw error;
  }
}

