import test from "node:test";
import assert from "node:assert/strict";
import { createApp, INVALID_JSON } from "../src/api.ts";
import type { Request } from "../src/api.ts";
import { sampleInvoices } from "../src/invoices.ts";

const DAY_MS = 86_400_000;

function validBody() {
  return {
    client: "Acme Corp",
    issued: "2026-03-01",
    netDays: 30,
    currency: "USD",
    items: [{ description: "Audit", quantity: 2, unitPriceCents: 12_500, taxRate: 0.16 }],
  };
}

function setup(count = 3) {
  let time = Date.UTC(2026, 10, 13);
  const app = createApp({ invoices: sampleInvoices(count), now: () => time });
  return {
    app,
    advance(ms: number) {
      time += ms;
    },
    post(body: unknown, headers: Record<string, string> = {}) {
      return app.handle({ method: "POST", path: "/invoices", headers, body });
    },
  };
}

test("POST /invoices creates an invoice with the next id", () => {
  const { app, post } = setup(3);
  const response = post(validBody());
  assert.equal(response.status, 201);
  assert.equal(response.headers.location, "/invoices/INV-01004");
  assert.equal(response.headers["content-type"], "application/json");
  assert.deepEqual(response.body, { id: "INV-01004", status: "draft", ...validBody() });
  assert.deepEqual(app.handle({ method: "GET", path: "/invoices/INV-01004" }).body, response.body);
  assert.equal(post(validBody()).headers.location, "/invoices/INV-01005");
});

test("created invoices show up in GET /invoices", () => {
  const { app, post } = setup(2);
  post({ ...validBody(), status: "sent" });
  const list = app.handle({ method: "GET", path: "/invoices" }).body as { items: Array<{ id: string; status: string; due: string }> };
  assert.deepEqual(list.items.map((item) => item.id), ["INV-01001", "INV-01002", "INV-01003"]);
  assert.equal(list.items[2]!.status, "sent");
  assert.equal(list.items[2]!.due, "2026-03-31");
});

test("the next id follows the highest existing id", () => {
  const invoices = sampleInvoices(2).map((invoice, i) => ({ ...invoice, id: ["INV-00042", "INV-00007"][i]! }));
  const app = createApp({ invoices });
  const response = app.handle({ method: "POST", path: "/invoices", body: validBody() });
  assert.equal(response.headers.location, "/invoices/INV-00043");
  const empty = createApp({ invoices: [] });
  assert.equal(empty.handle({ method: "POST", path: "/invoices", body: validBody() }).headers.location, "/invoices/INV-00001");
});

test("only known fields are kept and the id cannot be chosen", () => {
  const { post } = setup(1);
  const response = post({ ...validBody(), id: "INV-99999", extra: true });
  assert.equal((response.body as { id: string }).id, "INV-01002");
  assert.equal("extra" in (response.body as object), false);
});

test("invalid bodies return 400 invalid_invoice with a message", () => {
  const { post } = setup();
  const item = validBody().items[0]!;
  const cases: Array<[string, unknown]> = [
    ["not an object", [validBody()]],
    ["null", null],
    ["no body", undefined],
    ["missing client", { ...validBody(), client: undefined }],
    ["empty client", { ...validBody(), client: "" }],
    ["numeric client", { ...validBody(), client: 5 }],
    ["bad issued", { ...validBody(), issued: "2026-3-1" }],
    ["impossible issued", { ...validBody(), issued: "2026-02-30" }],
    ["negative netDays", { ...validBody(), netDays: -1 }],
    ["fractional netDays", { ...validBody(), netDays: 1.5 }],
    ["string netDays", { ...validBody(), netDays: "30" }],
    ["huge netDays", { ...validBody(), netDays: 1e9 }],
    ["bad currency", { ...validBody(), currency: "GBP" }],
    ["bad status", { ...validBody(), status: "overdue" }],
    ["null status", { ...validBody(), status: null }],
    ["no items", { ...validBody(), items: [] }],
    ["items not array", { ...validBody(), items: item }],
    ["item not object", { ...validBody(), items: [1] }],
    ["zero quantity", { ...validBody(), items: [{ ...item, quantity: 0 }] }],
    ["fractional quantity", { ...validBody(), items: [{ ...item, quantity: 1.5 }] }],
    ["negative price", { ...validBody(), items: [{ ...item, unitPriceCents: -1 }] }],
    ["fractional price", { ...validBody(), items: [{ ...item, unitPriceCents: 1.5 }] }],
    ["tax above 1", { ...validBody(), items: [{ ...item, taxRate: 1.01 }] }],
    ["negative tax", { ...validBody(), items: [{ ...item, taxRate: -0.1 }] }],
    ["string tax", { ...validBody(), items: [{ ...item, taxRate: "0.1" }] }],
    ["bad second item", { ...validBody(), items: [item, { ...item, quantity: "2" }] }],
    ["invalid JSON", INVALID_JSON],
  ];
  for (const [name, body] of cases) {
    const response = post(body);
    assert.equal(response.status, 400, name);
    const responseBody = response.body as { error: string; message: string };
    assert.equal(responseBody.error, "invalid_invoice", name);
    assert.equal(typeof responseBody.message, "string", name);
    assert.ok(responseBody.message.length > 0, name);
  }
  assert.match((post({ ...validBody(), items: [item, { ...item, quantity: 0 }] }).body as { message: string }).message, /items\[1\]\.quantity/);
  // Nothing was created by the failed requests.
  assert.equal(post(validBody()).headers.location, "/invoices/INV-01004");
});

test("boundary values are accepted", () => {
  const { post } = setup();
  const response = post({
    ...validBody(),
    netDays: 0,
    status: "void",
    currency: "MXN",
    items: [
      { description: "Free", quantity: 1, unitPriceCents: 0, taxRate: 0 },
      { description: "Taxed", quantity: 1, unitPriceCents: 100, taxRate: 1 },
    ],
  });
  assert.equal(response.status, 201);
});

test("the same key and body replays the first response and creates nothing", () => {
  const { app, post } = setup();
  const headers = { "idempotency-key": "key-1" };
  const first = post(validBody(), headers);
  assert.equal(first.status, 201);
  assert.equal(first.headers["idempotent-replay"], undefined);

  const reordered = { items: validBody().items, currency: "USD", netDays: 30, issued: "2026-03-01", client: "Acme Corp" };
  const second = post(reordered, headers);
  assert.equal(second.status, 201);
  assert.equal(second.headers["idempotent-replay"], "true");
