    ["items not array", { ...validBody(), items: item }],
    ["item not object", { ...validBody(), items: [1] }],
    ["zero quantity", { ...validBody(), items: [{ ...item, quantity: 0 }] }],
    ["fractional quantity", { ...validBody(), items: [{ ...item, quantity: 1.5 }] }],
    ["negative price", { ...validBody(), items: [{ ...item, unitPriceCents: -1 }] }],
    ["fractional price", { ...validBody(), items: [{ ...item, unitPriceCents: 1.5 }] }],
    ["tax above 1", { ...validBody(), items: [{ ...item, taxRate: 1.01 }] }],
    ["negative tax", { ...validBody(), items: [{ ...item, taxRate: -0.1 }] }],
    ["string tax", { ...validBody(), items: [{ ...item, taxRate: "0.1" }] }],
    ["bad second item", { ...validBody(), items: [item, { ...item, quantity: "2" }] }],
    ["invalid JSON", INVALID_JSON],
  ];
  for (const [name, body] of cases) {
    const response = post(body);
    assert.equal(response.status, 400, name);
    const responseBody = response.body as { error: string; message: string };
    assert.equal(responseBody.error, "invalid_invoice", name);
    assert.equal(typeof responseBody.message, "string", name);
    assert.ok(responseBody.message.length > 0, name);
  }
  assert.match((post({ ...validBody(), items: [item, { ...item, quantity: 0 }] }).body as { message: string }).message, /items\[1\]\.quantity/);
  // Nothing was created by the failed requests.
  assert.equal(post(validBody()).headers.location, "/invoices/INV-01004");
});

test("boundary values are accepted", () => {
  const { post } = setup();
  const response = post({
    ...validBody(),
    netDays: 0,
    status: "void",
    currency: "MXN",
    items: [
      { description: "Free", quantity: 1, unitPriceCents: 0, taxRate: 0 },
      { description: "Taxed", quantity: 1, unitPriceCents: 100, taxRate: 1 },
    ],
  });
  assert.equal(response.status, 201);
});

test("the same key and body replays the first response and creates nothing", () => {
  const { app, post } = setup();
  const headers = { "idempotency-key": "key-1" };
  const first = post(validBody(), headers);
  assert.equal(first.status, 201);
  assert.equal(first.headers["idempotent-replay"], undefined);

  const reordered = { items: validBody().items, currency: "USD", netDays: 30, issued: "2026-03-01", client: "Acme Corp" };
  const second = post(reordered, headers);
  assert.equal(second.status, 201);
  assert.equal(second.headers["idempotent-replay"], "true");
  assert.equal(second.headers.location, first.headers.location);
  assert.deepEqual(second.body, first.body);

  assert.equal(app.handle({ method: "GET", path: "/invoices/INV-01005" }).status, 404);
  assert.equal(post(validBody()).headers.location, "/invoices/INV-01005");
});

test("the same key with a different body returns 422", () => {
  const { post } = setup();
  const headers = { "idempotency-key": "key-1" };
  post(validBody(), headers);
  const response = post({ ...validBody(), netDays: 31 }, headers);
  assert.equal(response.status, 422);
  assert.deepEqual(response.body, { error: "idempotency_key_reused" });
  // Item order is part of the value.
  const items = [validBody().items[0]!, { ...validBody().items[0]!, quantity: 1 }];
  post({ ...validBody(), items }, { "idempotency-key": "key-2" });
  assert.equal(post({ ...validBody(), items: [...items].reverse() }, { "idempotency-key": "key-2" }).status, 422);
  // Invalid JSON with a used key is still a bad request.
  assert.equal(post(INVALID_JSON, headers).status, 400);
});

test("different keys create different invoices", () => {
  const { post } = setup();
  assert.equal(post(validBody(), { "idempotency-key": "a" }).headers.location, "/invoices/INV-01004");
  assert.equal(post(validBody(), { "idempotency-key": "b" }).headers.location, "/invoices/INV-01005");
});

test("keys are scoped to the x-api-key", () => {
  const { post } = setup();
  const first = post(validBody(), { "idempotency-key": "k", "x-api-key": "alice" });
  const other = post({ ...validBody(), client: "Globex" }, { "idempotency-key": "k", "x-api-key": "bob" });
  assert.equal(first.status, 201);
  assert.equal(other.status, 201);
  assert.notEqual(other.headers.location, first.headers.location);
});

test("a key expires 24 hours after its first use", () => {
  const { post, advance } = setup();
  const headers = { "idempotency-key": "key-1" };
  const first = post(validBody(), headers);
  advance(DAY_MS - 1);
  assert.equal(post(validBody(), headers).headers["idempotent-replay"], "true");
  assert.equal(post({ ...validBody(), netDays: 1 }, headers).status, 422);
  advance(1);
  const fresh = post({ ...validBody(), netDays: 1 }, headers);
  assert.equal(fresh.status, 201);
  assert.equal(fresh.headers["idempotent-replay"], undefined);
  assert.notEqual(fresh.headers.location, first.headers.location);
  // The key now belongs to the new body.
  assert.equal(post({ ...validBody(), netDays: 1 }, headers).headers["idempotent-replay"], "true");
});

test("a 400 is not stored, so the client can fix the body and retry", () => {
  const { post } = setup();
  const headers = { "idempotency-key": "key-1" };
  assert.equal(post({ ...validBody(), currency: "GBP" }, headers).status, 400);
  const fixed = post(validBody(), headers);
  assert.equal(fixed.status, 201);
  assert.equal(fixed.headers["idempotent-replay"], undefined);
});

test("a replay is not affected by changes to the returned response", () => {
  const { post } = setup();
  const headers = { "idempotency-key": "key-1" };
  const first = post(validBody(), headers);
  (first.body as { client: string }).client = "changed";
  first.headers.location = "/elsewhere";
  const replay = post(validBody(), headers);
  assert.equal((replay.body as { client: string }).client, "Acme Corp");
  assert.equal(replay.headers.location, "/invoices/INV-01004");
});

test("replays and rate limiting work together", () => {
  let time = 0;
  const app = createApp({ invoices: [], now: () => time, rateLimit: { capacity: 3, refillPerSecond: 1 } });
  const request: Request = { method: "POST", path: "/invoices", headers: { "idempotency-key": "k" }, body: validBody() };
  assert.equal(app.handle(request).headers["x-ratelimit-remaining"], "2");
  const replay = app.handle(request);
  assert.equal(replay.headers["idempotent-replay"], "true");
  assert.equal(replay.headers["x-ratelimit-remaining"], "1");
  app.handle(request);
  assert.equal(app.handle(request).status, 429);
  time += 1000; // AppOptions.now also drives the rate limiter.
  assert.equal(app.handle(request).status, 201);
});

test("methods other than GET and POST return 405, as does POST elsewhere", () => {
  const { app } = setup();
  for (const method of ["PUT", "PATCH", "DELETE"]) {
    assert.equal(app.handle({ method, path: "/invoices", body: validBody() }).status, 405, method);
  }
  assert.equal(app.handle({ method: "POST", path: "/invoices/INV-01001", body: validBody() }).status, 405);
  assert.equal(app.handle({ method: "POST", path: "/health" }).status, 405);
});
