import assert from "node:assert/strict";
import { canonicalJson, createIdempotencyStore } from "../src/idempotency.ts";

test("canonicalJson ignores key order but not array order", () => {
  assert.equal(canonicalJson({ a: 1, b: { c: [1, 2], d: null } }), canonicalJson({ b: { d: null, c: [1, 2] }, a: 1 }));
  assert.notEqual(canonicalJson([1, 2]), canonicalJson([2, 1]));
  assert.notEqual(canonicalJson({ a: "1" }), canonicalJson({ a: 1 }));
  assert.notEqual(canonicalJson(undefined), canonicalJson(null));
  assert.notEqual(canonicalJson({ "a,b": 1 }), canonicalJson({ a: 1, b: 1 }));
});

test("the store replays, detects conflicts and expires keys", () => {
  let time = 0;
  const store = createIdempotencyStore<{ n: number }>({ ttlMs: 100, now: () => time });
  assert.deepEqual(store.check("k", "f1"), { kind: "new" });
  store.save("k", "f1", { n: 1 });
  assert.deepEqual(store.check("k", "f1"), { kind: "replay", response: { n: 1 } });
  assert.deepEqual(store.check("k", "f2"), { kind: "conflict" });
  time = 99;
  assert.deepEqual(store.check("k", "f2"), { kind: "conflict" });
  time = 100;
  assert.deepEqual(store.check("k", "f2"), { kind: "new" });
  store.save("k", "f2", { n: 2 });
  time = 150;
  assert.deepEqual(store.check("k", "f2"), { kind: "replay", response: { n: 2 } });
});

test("the default time to live is 24 hours", () => {
  let time = 0;
  const store = createIdempotencyStore<number>({ now: () => time });
  store.save("k", "f", 1);
  time = 24 * 60 * 60 * 1000 - 1;
  assert.equal(store.check("k", "f").kind, "replay");
  time += 1;
  assert.equal(store.check("k", "f").kind, "new");
});
